ANSWER: import re

def evaluate_cell(ref, cells, memo):
    if ref in memo:
        return memo[ref]
    raw = cells[ref]
    if raw.isdigit() or (raw.startswith('-') and raw[1:].isdigit()):
        val = int(raw)
    else:
        # Formula like =A1+B2
        expr = raw[1:]  # remove '='
        tokens = re.findall(r'[A-Z]\d+|[+\-*/]', expr)
        # Simple evaluation: replace each cell ref with its evaluated value, then eval (safe because only ints and operators)
        # Build a string with evaluated numbers.
        eval_str = ''
        for token in tokens:
            if token in '+-*/':
                eval_str += token
            else:
                eval_str += str(evaluate_cell(token, cells, memo))
        val = eval(eval_str)  # safe given input constraints
    memo[ref] = val
    return val

def evaluate_spreadsheet(cells):
    memo = {}
    for ref in cells:
        evaluate_cell(ref, cells, memo)
    return memo

