    if abs(len(reference) - len(target)) > 1:
        return False
    i = 0
    j = 0
    mutations = 0
    while i < len(reference) and j < len(target):
        if reference[i] != target[j]:
            if mutations == 1:
                return False
            mutations += 1
            if len(reference) > len(target):
                i += 1
            elif len(reference) < len(target):
                j += 1
            else:
                i += 1
                j += 1
        else:
            i += 1
            j += 1
    if i < len(reference) or j < len(target):
        mutations += 1
    return mutations == 1

