def is_one_edit_distance(s, t):
    if len(s) < len(t):
        return is_one_edit_distance(t, s)
    if len(s) - len(t) > 1:
        return False
    prev = list(range(len(t) + 1))
    curr = [0] * (len(t) + 1)
    for i in range(1, len(s) + 1):
        curr[0] = i
        for j in range(1, len(t) + 1):
            if s[i - 1] == t[j - 1]:
                curr[j] = prev[j - 1]
            else:
                curr[j] = 1 + min(prev[j - 1], prev[j], curr[j - 1])
        prev = curr[:]
    return curr[-1] == 1

