def check_typo_distance(str1, str2):
    if abs(len(str1) - len(str2)) > 1:
        return False
    i, j = 0, 0
    edits = 0
    while i < len(str1) and j < len(str2):
        if str1[i] != str2[j]:
            edits += 1
            if edits > 1:
                return False
            if len(str1) > len(str2):
                i += 1
            elif len(str1) < len(str2):
                j += 1
            else:
                i += 1
                j += 1
        else:
            i += 1
            j += 1
    return edits + (len(str1) - i) + (len(str2) - j) == 1

