class QueryCache:
    def __init__(self, capacity):
        self.capacity = capacity
        self.cache = {}
        self.order = []

    def fetch(self, query_string):
        if query_string in self.cache:
            self.order.remove(query_string)
            self.order.append(query_string)
            return self.cache[query_string]
        return None

    def store(self, query_string, result_set):
        if query_string in self.cache:
            self.order.remove(query_string)
        elif len(self.cache) >= self.capacity:
            oldest = self.order.pop(0)
            del self.cache[oldest]
        self.cache[query_string] = result_set
        self.order.append(query_string)

