def evaluate_spreadsheet(sheet):
    evaluated = {}
    visiting = set()

    def eval_cell(cell_id):
        if cell_id in evaluated:
            return evaluated[cell_id]
        if cell_id in visiting:
            raise ValueError("Circular dependency detected")

        visiting.add(cell_id)
        val = sheet[cell_id]

        if isinstance(val, int):
            res = val
        elif val.startswith('='):
            parts = val[1:].split('+')
            res = eval_cell(parts[0]) + eval_cell(parts[1])

        visiting.remove(cell_id)
        evaluated[cell_id] = res
        return res

    for cell in sheet:
        eval_cell(cell)

    return evaluated

