def calculate_build_times(build_graph):
    cache = {}
    def get_time(job):
        if job in cache:
            return cache[job]
        value = build_graph[job]
        if isinstance(value, int):
            cache[job] = value
        else:
            deps = value[1:].split('+')
            cache[job] = sum(get_time(dep) for dep in deps)
        return cache[job]

    return {job: get_time(job) for job in build_graph}

