import json

def extract_errors(log_feed):
    lines = log_feed.strip().split('\n')
    errors = []
    for line in lines:
        if line.startswith('[ERROR]'):
            msg = line.split('] ', 1)[1]
            errors.append({'severity': 'ERROR', 'details': msg})
    return json.dumps(errors)

